INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ur'), 'A1', 'greetings', 'Greetings', 'Greet people the Hyderabadi way and introduce yourself in Urdu.', 'Your first evening in a rented flat in Tolichowki. Nawab sahab, your landlord, comes to welcome you.', 'Greet with “Assalaam alaikum” (answered “Walaikum assalaam”) or “Aadaab”. Hyderabadi Urdu has its own words: “hau” (yes), “nakko” (no, don''t) and “kya re?” (what''s up?), used with friends.', 1, 'published', datetime('now'), datetime('now'), 1);
