INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ur') AND slug = 'polite-requests'), (SELECT id FROM languages WHERE code = 'en'), 'Polite requests: “-iye”, “-o” and “-na”', 'Urdu asks politely with “aap” and verbs ending in -iye: “dijiye” (please give), “boliye” (please say), “bulaaiye” (please call). In the market and with friends the “tum” form in -o is common: “chalo”, “roko”, “daalo”; the -na form (“dena”) is a friendly request.');
