INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ur') AND slug = 'hyderabadi-words'), (SELECT id FROM languages WHERE code = 'en'), 'Hyderabadi words: “hau”, “nakko”, “kya re”', 'Hyderabad''s Urdu (Dakhini) has its own everyday words: “hau” (yes), “nakko” (no, don''t), “kya re?” (what''s up?) and “idhar / udhar” (here / there). They are informal: use them with friends and in the market, and “ji haan” / “ji nahi” with elders.');
